CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'client',password_hash TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invites(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS auth_attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS entitlements(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL,source TEXT NOT NULL,status TEXT NOT NULL,expires INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS missions(id INTEGER NOT NULL,lang TEXT NOT NULL,draft TEXT NOT NULL,published TEXT,status TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id,lang));
CREATE TABLE IF NOT EXISTS state(user_id TEXT NOT NULL,mission_id INTEGER NOT NULL,done INTEGER NOT NULL DEFAULT 0,favorite INTEGER NOT NULL DEFAULT 0,plan INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',updated_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,mission_id));
CREATE TABLE IF NOT EXISTS worksheets(user_id TEXT NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL DEFAULT '[]',updated_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,kind));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webhook_events(id INTEGER PRIMARY KEY,integration TEXT,event_id TEXT,status TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(integration,event_id));
